#include <stdint.h>

void vectorized_s1113(int iterations, int LEN_1D, float* a, float* b)
{
    float scalar_val = a[LEN_1D/2];
    for (int nl = 0; nl < 2*iterations; nl++) {
        int i = 0;
        int limit = LEN_1D - (LEN_1D % 8);
        for (; i < limit; i += 8) {
            a[i+0] = scalar_val + b[i+0];
            a[i+1] = scalar_val + b[i+1];
            a[i+2] = scalar_val + b[i+2];
            a[i+3] = scalar_val + b[i+3];
            a[i+4] = scalar_val + b[i+4];
            a[i+5] = scalar_val + b[i+5];
            a[i+6] = scalar_val + b[i+6];
            a[i+7] = scalar_val + b[i+7];
        }
        for (; i < LEN_1D; i++) {
            a[i] = scalar_val + b[i];
        }
    }
}

void s1113_opt(int iterations, int LEN_1D, float* a, float* b) {
    int mid = LEN_1D / 2;
    float a_mid, new_mid;

    for (int nl = 0; nl < 2 * iterations; nl++) {
        // Store original mid value
        a_mid = a[mid];

        // First half: i = 0 to mid-1 (uses original a[mid])
        for (int i = 0; i < mid; i++) {
            a[i] = a_mid + b[i];
        }

        // Compute new mid value in temporary
        new_mid = a_mid + b[mid];

        // Second half: i = mid+1 to LEN_1D-1 (uses computed new_mid)
        for (int i = mid + 1; i < LEN_1D; i++) {
            a[i] = new_mid + b[i];
        }

        // Finally update the actual mid element
        a[mid] = new_mid;
    }
}
